mapper.select:

SELECT
  count(*) totcnt
FROM
  ttokssaemdb.attendance attend


    AND attend.branchid = #{session_branchid}


    AND attend.method LIKE #{likeQuery}

SELECT R1.* FROM( SELECT branch.branchid, branch.branchname, member.memberid, member.membername, attend.method, DATE_FORMAT(attend.regdate, '%Y-%m-%d %H:%i:%s') regdate FROM ttokssaemdb.attendance attend, ttokssaemdb.branch branch, ttokssaemdb.member member
AND attend.branchid = branch.branchid AND attend.memberid = member.memberid
AND attend.branchid = #{session_branchid}
AND attend.method LIKE #{likeQuery}
attend.attendanceid attend.regdate DESC ASC DESC
) R1
LIMIT ${length} OFFSET ${start}
